mapper.insert:
INSERT INTO member_inquiry_images (
    inquiry_id,
    image_url,
    display_order
) VALUES (
    #{inquiryId},
    #{imageUrl},
    #{displayOrder}
)

mapper.select:
SELECT inquiry_image_id AS inquiryImageId, inquiry_id AS inquiryId, image_url AS imageUrl, display_order AS displayOrder FROM member_inquiry_images WHERE inquiry_id IN
#{inquiryId}
ORDER BY inquiry_id ASC, display_order ASC

SELECT

FROM member_inquiries i
INNER JOIN members m ON m.member_id = i.member_id
WHERE i.member_id = #{memberId}

    AND i.inquiry_id < #{cursor.cursorInquiryId}

ORDER BY i.inquiry_id DESC
LIMIT #{cursor.size}

SELECT

FROM member_inquiries i
INNER JOIN members m ON m.member_id = i.member_id
WHERE i.inquiry_id = #{inquiryId}
    AND i.member_id = #{memberId}

SELECT

FROM member_inquiries i
INNER JOIN members m ON m.member_id = i.member_id
WHERE 1 = 1

    AND i.inquiry_status = #{cursor.inquiryStatus}


    AND i.inquiry_id < #{cursor.cursorInquiryId}

ORDER BY i.inquiry_id DESC
LIMIT #{cursor.size}
